refentry.refsect1:
&reftitle.description;
intsubstr_count stringhaystack stringneedle intoffset0 intnulllength&null;
substr_count restituisce il numero di volte in cui la sottostringa needle compare nella stringa haystack. Si noti che needle è sensibile alle maiuscole/minuscole.
Questa funzione non conta le sottostringhe sovrapposte. Si veda l'esempio seguente!

  &reftitle.examples;



    Esempio di substr_count


<?php
$text = 'Gira e rigira';
echo strlen($text), PHP_EOL; // 13

echo substr_count($text, 'ra'), PHP_EOL; // 2

// la stringa viene ridotta a 'a e rigira', quindi stampa 1
echo substr_count($text, 'ra', 3), PHP_EOL;

// il testo viene ridotto a 'a e', quindi stampa 0
echo substr_count($text, 'ra', 3, 3), PHP_EOL;

// stampa solo 1, perché non conta le sottostringhe sovrapposte
$text2 = 'gcdgcdgcd';
echo substr_count($text2, 'gcdgcd'), PHP_EOL;

// lancia un'eccezione perché 5+10 > 13
echo substr_count($text, 'ra', 5, 10), PHP_EOL;
?>
